/* Copertura dei turni: conteggi del pianificato, disponibilità e sostituzioni confermate. */
let staffingRequest=0,staffingData=null,staffingSection='coverage';
const staffingWeekdays=['Lunedì','Martedì','Mercoledì','Giovedì','Venerdì','Sabato','Domenica'];
const staffingAvailabilityLabels={available:'Disponibile',unavailable:'Non disponibile',preferred:'Preferenza di presenza'};
const staffingProposalLabels={pending:'Da valutare',accepted:'Accettata · pianificato registrato',rejected:'Rifiutata'};
const staffingCoverageLabels={unconfigured:'Minimo da configurare',uncovered:'Da coprire',extra:'Sopra il minimo',covered:'Coperta'};
function staffingOwner(){return [auth?.user?.id,cid,month].join('|')}
function staffingAlive(owner){return tab==='copertura'&&owner===staffingOwner()}
function staffingDate(day){return day?new Date(day+'T12:00:00').toLocaleDateString('it-IT'):'—'}
function staffingSlot(id){return staffingData.slots.find(s=>s.id===id)?.label||id}
function staffingOptions(rows,value,key='id',label='label'){return rows.map(r=>`<option value="${esc(r[key])}" ${String(r[key])===String(value)?'selected':''}>${esc(r[label])}</option>`).join('')}
async function renderStaffing(){
 const owner=staffingOwner(),request=++staffingRequest,data=await api(`staffing?cid=${encodeURIComponent(cid)}&month=${encodeURIComponent(month)}`);
 if(!staffingAlive(owner)||request!==staffingRequest)return;staffingData=data;
 if(!data.permissions.availability&&['availability','proposals'].includes(staffingSection))staffingSection='coverage';
 const sections=[['coverage','Copertura del mese'],['requirements','Fabbisogni'],...(data.permissions.availability?[['availability','Disponibilità'],['proposals','Sostituzioni']]:[])];
 $('#content').innerHTML=`<section class="panel staffing-intro"><p class="eyebrow">ORGANIZZAZIONE DEI TURNI</p><h2>La presenza giusta, nella fascia giusta.</h2><p>Confronta il personale pianificato con i minimi indicati dalla struttura. Le disponibilità aiutano a evidenziare i turni da rivedere; le sostituzioni aggiungono il pianificato solo dopo la conferma del responsabile.</p><p class="note">${esc(data.note)}</p>${data.closed?'<p class="note">Il mese è chiuso: le sostituzioni non possono aggiungere turni al registro.</p>':''}</section><div class="staffing-tabs">${sections.map(([key,title])=>`<button class="btn ${staffingSection===key?'primary':''}" data-staffing-section="${key}">${title}</button>`).join('')}</div><div id="staffingBody"></div>`;
 document.querySelectorAll('[data-staffing-section]').forEach(b=>b.onclick=()=>{staffingSection=b.dataset.staffingSection;staffingDraw()});staffingDraw();
}
function staffingDraw(){
 if(!staffingData||tab!=='copertura')return;
 document.querySelectorAll('[data-staffing-section]').forEach(b=>b.classList.toggle('primary',b.dataset.staffingSection===staffingSection));
 ({coverage:staffingCoverage,requirements:staffingRequirements,availability:staffingAvailability,proposals:staffingProposals})[staffingSection]();
}
function staffingCoverage(){
 const d=staffingData;
 $('#staffingBody').innerHTML=`<div class="staffing-metrics"><section class="panel"><span>Fasce e qualifiche con minimo</span><strong>${d.summary.configured}</strong></section><section class="panel"><span>Fasce e qualifiche da coprire</span><strong>${d.summary.uncovered}</strong></section><section class="panel"><span>Posti mancanti sulle fasce</span><strong>${d.summary.missing}</strong></section></div><section class="panel"><div class="staffing-toolbar"><div class="field"><label for="staffingDay">Giorno</label><input id="staffingDay" type="date" min="${esc(d.month)}-01"></div><div class="field"><label for="staffingRole">Qualifica</label><select id="staffingRole"><option value="">Tutte le qualifiche</option>${d.roles.map(r=>`<option value="${esc(r)}">${esc(r)}</option>`).join('')}</select></div><div class="field"><label for="staffingState">Copertura</label><select id="staffingState"><option value="">Tutti gli stati</option>${Object.entries(staffingCoverageLabels).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></div><button class="btn" id="staffingRefresh">Aggiorna</button></div><p class="muted smalltext">Il confronto usa il pianificato. Il consuntivo è mostrato separatamente. Ogni persona conta una sola volta per giorno, fascia e qualifica; turni senza orari o in conflitto vengono esclusi dal conteggio.</p><div class="staffing-table-wrap"><table class="data-table staffing-table"><thead><tr><th>Giorno</th><th>Fascia</th><th>Qualifica</th><th>Minimo</th><th>Pianificati</th><th>Consuntivi</th><th>Mancanti</th><th>Da verificare</th><th>Stato</th></tr></thead><tbody id="staffingRows"></tbody></table></div></section>${d.problems.length?`<section class="panel"><h3>Turni da verificare</h3><ul class="staffing-problems">${d.problems.map(p=>`<li><b>${esc(p.person_name)}</b> · ${staffingDate(p.day)} · ${esc(staffingSlot(p.slot))} · ${p.layer==='planned'?'Pianificato':'Consuntivo'}<span>${esc(p.reason)}</span></li>`).join('')}</ul></section>`:''}`;
 const draw=()=>{const day=$('#staffingDay').value,role=$('#staffingRole').value,status=$('#staffingState').value;const rows=d.rows.filter(r=>(!day||r.day===day)&&(!role||r.role===role)&&(!status||r.state===status));$('#staffingRows').innerHTML=rows.map(r=>`<tr><td>${staffingDate(r.day)}</td><td>${esc(staffingSlot(r.slot))}</td><td>${esc(r.role)}</td><td>${r.minimum??'—'}</td><td>${r.planned}</td><td>${r.actual}</td><td>${r.gap??'—'}</td><td>${r.excluded}</td><td><span class="tag ${r.state==='uncovered'?'warn':r.state==='covered'?'green':''}">${esc(staffingCoverageLabels[r.state])}</span></td></tr>`).join('')||'<tr><td colspan="9" class="muted">Nessun turno o fabbisogno nei filtri. Configura i minimi oppure registra il pianificato nelle Presenze.</td></tr>'};
 $('#staffingDay').onchange=draw;$('#staffingRole').onchange=draw;$('#staffingState').onchange=draw;$('#staffingRefresh').onclick=()=>renderStaffing().catch(e=>toast(e.message));draw();
}
function staffingRequirements(){
 const d=staffingData;
 function rows(key){return d.requirements[key].map(r=>`<tr><td>${key==='weekly'?staffingWeekdays[r.weekday]:staffingDate(r.day)}</td><td>${esc(staffingSlot(r.slot))}</td><td>${esc(r.role)}</td><td>${r.minimum}</td></tr>`).join('')||'<tr><td colspan="4" class="muted">Nessun minimo configurato.</td></tr>'}
 $('#staffingBody').innerHTML=`<section class="panel"><div class="staffing-toolbar"><div><h3>Minimi della struttura</h3><p class="muted">I minimi sono riferimenti organizzativi scelti dalla struttura. Le eccezioni per data sostituiscono il minimo settimanale della stessa fascia e qualifica; zero permette di annullare un minimo in una data specifica.</p></div>${d.permissions.configure?'<button class="btn primary" id="staffingEditRequirements">Modifica fabbisogni</button>':'<span class="tag">Configurazione riservata al responsabile</span>'}</div><h4>Settimana tipo</h4><div class="staffing-table-wrap"><table class="data-table"><thead><tr><th>Giorno</th><th>Fascia</th><th>Qualifica</th><th>Minimo</th></tr></thead><tbody>${rows('weekly')}</tbody></table></div><h4>Eccezioni per data</h4><div class="staffing-table-wrap"><table class="data-table"><thead><tr><th>Data</th><th>Fascia</th><th>Qualifica</th><th>Minimo</th></tr></thead><tbody>${rows('overrides')}</tbody></table></div><p class="muted smalltext">Versione ${d.requirements.version}. Il salvataggio non modifica i turni già registrati.</p></section>`;
 if(d.permissions.configure)$('#staffingEditRequirements').onclick=staffingEditRequirements;
}
function staffingModal(title,body,label,submit){
 const owner=staffingOwner();let busy=false,dirty=false;
 modal(title,`<form id="staffingForm">${body}<p id="staffingFormError" role="alert" class="error" hidden></p></form>`,`<button class="btn primary" type="submit" form="staffingForm" id="staffingFormSave">${esc(label)}</button>`);
 const dialog=$('#modal'),form=$('#staffingForm'),save=$('#staffingFormSave');form.oninput=()=>{dirty=true};
 const close=()=>!busy&&(!dirty||confirm('Chiudere senza salvare le modifiche?'));
 dialog.oncancel=e=>{if(!close())e.preventDefault()};dialog.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>{if(close())dialog.close()});
 form.onsubmit=async e=>{e.preventDefault();if(busy||!form.reportValidity())return;busy=true;save.disabled=true;form.inert=true;$('#staffingFormError').hidden=true;try{await submit();if(!staffingAlive(owner)||$('#staffingForm')!==form)return;dirty=false;dialog.oncancel=null;dialog.close();await renderStaffing();toast('Aggiornamento salvato.')}catch(error){if(staffingAlive(owner)&&$('#staffingForm')===form){$('#staffingFormError').textContent=error.message;$('#staffingFormError').hidden=false}}finally{busy=false;form.inert=false;save.disabled=false}};
}
function staffingEditRequirements(){
 const d=staffingData,selectedCid=d.cid,version=d.requirements.version;
 const activeSlots=d.slots.filter(s=>s.active);
 if(!activeSlots.length||!d.roles.length){toast('Configura prima almeno una fascia e una qualifica attive.');return}
 const drafts={weekly:structuredClone(d.requirements.weekly),overrides:structuredClone(d.requirements.overrides)};
 staffingModal('Fabbisogni · '+d.center_name,`<p class="muted">Ogni giorno, fascia e qualifica può comparire una sola volta. Una data specifica prevale sulla settimana tipo.</p><h3>Settimana tipo</h3><div id="staffingWeeklyRows"></div><button type="button" class="btn" id="staffingAddWeekly">Aggiungi minimo settimanale</button><h3>Eccezioni per data</h3><div id="staffingOverrideRows"></div><button type="button" class="btn" id="staffingAddOverride">Aggiungi eccezione</button>`,'Salva fabbisogni',()=>{read();return api('staffing_requirements_save',{cid:selectedCid,version,...drafts})});
 function read(){for(const key of ['weekly','overrides'])drafts[key]=Array.from(document.querySelectorAll(`[data-staffing-requirement="${key}"]`)).map(row=>({...key==='weekly'?{weekday:Number(row.querySelector('[data-field=when]').value)}:{day:row.querySelector('[data-field=when]').value},slot:row.querySelector('[data-field=slot]').value,role:row.querySelector('[data-field=role]').value,minimum:Number(row.querySelector('[data-field=minimum]').value)}))}
 function draw(){for(const key of ['weekly','overrides']){
  const target=key==='weekly'?'#staffingWeeklyRows':'#staffingOverrideRows';$(target).innerHTML=drafts[key].map((r,i)=>`<div class="staffing-requirement-row" data-staffing-requirement="${key}"><label>${key==='weekly'?'Giorno':'Data'}${key==='weekly'?`<select data-field="when" aria-label="Giorno della settimana">${staffingWeekdays.map((w,j)=>`<option value="${j}" ${r.weekday===j?'selected':''}>${w}</option>`).join('')}</select>`:`<input data-field="when" type="date" required value="${esc(r.day)}" aria-label="Data dell’eccezione">`}</label><label>Fascia<select data-field="slot" aria-label="Fascia">${staffingOptions(activeSlots,r.slot)}</select></label><label>Qualifica<select data-field="role" aria-label="Qualifica">${d.roles.map(role=>`<option value="${esc(role)}" ${role===r.role?'selected':''}>${esc(role)}</option>`).join('')}</select></label><label>Minimo<input data-field="minimum" type="number" min="0" max="1000" step="1" required value="${r.minimum}" aria-label="Personale minimo"></label><button type="button" class="btn small" data-staffing-remove="${key}|${i}" aria-label="Rimuovi riga di fabbisogno">Rimuovi</button></div>`).join('')||'<p class="muted smalltext">Nessuna riga.</p>';
 }
 document.querySelectorAll('[data-staffing-remove]').forEach(b=>b.onclick=()=>{read();const [key,index]=b.dataset.staffingRemove.split('|');drafts[key].splice(Number(index),1);draw();$('#staffingForm').dispatchEvent(new Event('input'))});}
 $('#staffingAddWeekly').onclick=()=>{read();drafts.weekly.push({weekday:0,slot:activeSlots[0].id,role:d.roles[0],minimum:1});draw();$('#staffingForm').dispatchEvent(new Event('input'))};
 $('#staffingAddOverride').onclick=()=>{read();drafts.overrides.push({day:d.month+'-01',slot:activeSlots[0].id,role:d.roles[0],minimum:0});draw();$('#staffingForm').dispatchEvent(new Event('input'))};draw();
}
function staffingAvailability(){
 const d=staffingData;if(!d.permissions.availability)return;
 $('#staffingBody').innerHTML=`<section class="panel"><div class="staffing-toolbar"><div><h3>Disponibilità del personale</h3><p class="muted">Registra periodi disponibili, non disponibili o preferiti. Una preferenza non assegna un turno. Le indisponibilità escludono i turni pianificati dai conteggi e bloccano le sostituzioni in conflitto.</p></div><button class="btn primary" id="staffingNewAvailability">Nuova disponibilità</button></div><div class="staffing-table-wrap"><table class="data-table staffing-table"><thead><tr><th>Persona</th><th>Dal</th><th>Al</th><th>Indicazione</th><th>Nota riservata</th><th>Stato</th><th>Azione</th></tr></thead><tbody>${d.availability.map(a=>`<tr><td>${esc(a.person_name)}</td><td>${staffingDate(a.start)}</td><td>${staffingDate(a.end)}</td><td>${esc(staffingAvailabilityLabels[a.status])}</td><td>${esc(a.note||'—')}</td><td>${a.active?'Attiva':'Ritirata'}</td><td><button class="btn small" data-staffing-availability="${esc(a.id)}">Modifica</button></td></tr>`).join('')||'<tr><td colspan="7" class="muted">Nessuna disponibilità registrata nel mese.</td></tr>'}</tbody></table></div><p class="muted smalltext">Note visibili solo a HR e responsabili autorizzati. Un’assenza approvata va registrata anche nel registro presenze: questa pagina non gestisce richieste di ferie del dipendente.</p></section>`;
 $('#staffingNewAvailability').onclick=()=>staffingEditAvailability();document.querySelectorAll('[data-staffing-availability]').forEach(b=>b.onclick=()=>staffingEditAvailability(d.availability.find(a=>a.id===b.dataset.staffingAvailability)));
}
function staffingEditAvailability(item){
 const d=staffingData,selectedCid=d.cid;
 if(!d.people.length){toast('Aggiungi prima una persona attiva alla struttura.');return}
 const personOptions=d.people.some(p=>p.id===item?.pid)?d.people:[...d.people,...(item?[{id:item.pid,name:item.person_name}]:[])];
 staffingModal(item?'Aggiorna disponibilità':'Nuova disponibilità',`<div class="formgrid"><div class="field full"><label for="staffingAvailabilityPerson">Persona</label><select id="staffingAvailabilityPerson" ${item?'disabled':''}>${staffingOptions(personOptions,item?.pid,'id','name')}</select></div><div class="field"><label for="staffingAvailabilityFrom">Dal giorno</label><input type="date" id="staffingAvailabilityFrom" required value="${esc(item?.start||d.month+'-01')}"></div><div class="field"><label for="staffingAvailabilityTo">Al giorno incluso</label><input type="date" id="staffingAvailabilityTo" required value="${esc(item?.end||d.month+'-01')}"></div><div class="field full"><label for="staffingAvailabilityStatus">Indicazione</label><select id="staffingAvailabilityStatus">${Object.entries(staffingAvailabilityLabels).map(([key,label])=>`<option value="${key}" ${key===(item?.status||'unavailable')?'selected':''}>${label}</option>`).join('')}</select></div><div class="field full"><label for="staffingAvailabilityNote">Nota riservata ai referenti HR</label><textarea id="staffingAvailabilityNote" maxlength="1000">${esc(item?.note||'')}</textarea></div><label class="check full"><input type="checkbox" id="staffingAvailabilityActive" ${item?.active===0?'':'checked'}>Indicazione attiva (togli la spunta per ritirarla)</label></div>`,'Salva disponibilità',()=>api('staffing_availability_save',{cid:selectedCid,pid:$('#staffingAvailabilityPerson').value,id:item?.id||'',version:item?.version||0,from:$('#staffingAvailabilityFrom').value,to:$('#staffingAvailabilityTo').value,status:$('#staffingAvailabilityStatus').value,note:$('#staffingAvailabilityNote').value,active:$('#staffingAvailabilityActive').checked}));
}
function staffingProposals(){
 const d=staffingData;if(!d.permissions.propose)return;
 $('#staffingBody').innerHTML=`<section class="panel"><div class="staffing-toolbar"><div><h3>Sostituzioni da altre strutture</h3><p class="muted">Scegli una persona già presente in entrambe le sedi e collegata in Personale di gruppo. La proposta viene controllata su disponibilità e sovrapposizioni; solo il responsabile della destinazione o l’amministratore può accettarla e registrare il pianificato.</p></div><button class="btn primary" id="staffingNewProposal" ${d.closed?'disabled':''}>Proponi sostituzione</button></div>${!d.candidates.length?'<p class="note">Non ci sono persone attive collegate a un’altra struttura accessibile al tuo ruolo. Il collegamento si gestisce esplicitamente in Personale di gruppo.</p>':''}<div class="staffing-proposal-list">${d.proposals.map(p=>`<article class="staffing-proposal"><div class="staffing-toolbar"><h4>${esc(p.person_name)}</h4><span class="tag ${p.status==='accepted'?'green':''}">${esc(staffingProposalLabels[p.status])}</span></div><p>${esc(p.origin_name)} → ${esc(p.center_name)} · ${staffingDate(p.day)} · ${esc(staffingSlot(p.slot))}</p><p>${esc(p.note)}</p><p class="muted smalltext">Proposta da ${esc(p.actor)} · ${esc(p.stamp)} · versione ${p.version}</p>${p.decision_note?`<p><b>Valutazione:</b> ${esc(p.decision_note)}</p><p class="muted smalltext">${esc(p.decided_by)} · ${esc(p.decided_at)}</p>`:''}${p.status==='pending'&&d.permissions.decide?`<div class="actions"><button class="btn primary" data-staffing-decide="accept" data-id="${esc(p.id)}" ${d.closed?'disabled':''}>Accetta e pianifica</button><button class="btn" data-staffing-decide="reject" data-id="${esc(p.id)}">Rifiuta</button></div>`:''}</article>`).join('')||'<p class="muted">Nessuna proposta nel mese selezionato.</p>'}</div></section>`;
 $('#staffingNewProposal').onclick=staffingEditProposal;document.querySelectorAll('[data-staffing-decide]').forEach(b=>b.onclick=()=>staffingDecide(d.proposals.find(p=>p.id===b.dataset.id),b.dataset.staffingDecide));
}
function staffingEditProposal(){
 const d=staffingData,selectedCid=d.cid;
 if(!d.candidates.length){toast('Collega prima le anagrafiche della stessa persona nelle due sedi autorizzate.');return}
 const slots=d.slots.filter(s=>s.active),codes=d.codes.filter(c=>c.active&&c.kind==='work');if(!slots.length||!codes.length){toast('Configura una fascia e una causale di lavoro attive.');return}
 staffingModal('Proponi sostituzione',`<p class="note">Destinazione: ${esc(d.center_name)}. Le sedi di origine proposte sono solo quelle accessibili al tuo ruolo. Gli orari seguono la fascia della destinazione.</p><div class="formgrid"><div class="field full"><label for="staffingProposalPerson">Persona e struttura di origine</label><select id="staffingProposalPerson">${d.candidates.map((p,i)=>`<option value="${i}">${esc(p.name)} · ${esc(p.origin_name)}</option>`).join('')}</select></div><div class="field"><label for="staffingProposalDay">Giorno del turno</label><input type="date" id="staffingProposalDay" required value="${esc(d.month)}-01"></div><div class="field"><label for="staffingProposalSlot">Fascia di destinazione</label><select id="staffingProposalSlot">${staffingOptions(slots,slots[0].id)}</select></div><div class="field full"><label for="staffingProposalCode">Causale di lavoro</label><select id="staffingProposalCode" required></select></div><div class="field full"><label for="staffingProposalNote">Motivazione della sostituzione</label><textarea id="staffingProposalNote" minlength="8" maxlength="1000" required></textarea></div></div>`,'Invia proposta',()=>{const person=d.candidates[Number($('#staffingProposalPerson').value)];return api('staffing_propose',{cid:selectedCid,pid:person.pid,origin_cid:person.origin_cid,origin_pid:person.origin_pid,day:$('#staffingProposalDay').value,slot:$('#staffingProposalSlot').value,code:$('#staffingProposalCode').value,note:$('#staffingProposalNote').value})});
 const update=()=>{const available=codes.filter(c=>!c.allowed_slots.length||c.allowed_slots.includes($('#staffingProposalSlot').value));$('#staffingProposalCode').innerHTML=available.length?staffingOptions(available,available[0].id):'<option value="">Nessuna causale per questa fascia</option>'};$('#staffingProposalSlot').onchange=update;update();
}
function staffingDecide(item,decision){
 staffingModal(decision==='accept'?'Conferma sostituzione e pianifica':'Rifiuta proposta',`<p><b>${esc(item.person_name)}</b> · ${staffingDate(item.day)} · ${esc(staffingSlot(item.slot))}</p><p>${esc(item.origin_name)} → ${esc(item.center_name)}</p>${decision==='accept'?'<p class="note">Il comando aggiunge un turno al pianificato della destinazione. Non modifica il consuntivo. Se presenze o disponibilità sono cambiate, rifiuta la proposta e chiedine una aggiornata.</p>':''}<div class="field"><label for="staffingDecisionNote">Motivazione / controllo effettuato</label><textarea id="staffingDecisionNote" required minlength="8" maxlength="1000"></textarea></div>${decision==='accept'?'<label class="check"><input id="staffingDecisionConfirm" type="checkbox" required>Confermo la persona, il giorno e la fascia da pianificare.</label>':''}`,decision==='accept'?'Conferma e registra pianificato':'Conferma rifiuto',()=>api('staffing_decide',{id:item.id,version:item.version,decision,note:$('#staffingDecisionNote').value}));
}
